/// <summary>
/// Purch table COC form
/// </summary>
[ExtensionOf(FormDataSourcestr(PurchTable, PurchTable))]
final class METPurchTableFormPurchTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Create COC method 
    /// </summary>
    /// <param name = "append">Boolean value</param>
    void  create(boolean  append)
    {
        next create(append);

        FormDataSource          PurchTableDataSource = this as FormDataSource;
        FormDataSource          METPurchTableDataSource = PurchTableDataSource.formRun().dataSource(formDataSourceStr(PurchTable,METpurchTable));

        METpurchTable           METpurchTable = MetPurchTableDataSource.cursor();
        if(!METpurchTable)
        {
            METpurchTable.data(METpurchTable::findByPurchTable(PurchTableDataSource.cursor().recid));
            METpurchTable.reread();
        }
    }
